    for lane in 0..rows { v[(base + 35) * stride + lane] = mul(ctx.constant(3), &v[(base + 31) * stride + lane]); }
    for lane in 0..rows { v[(base + 46) * stride + lane] = add(&v[(base + 37) * stride + lane], &v[(base + 35) * stride + lane]); }
