    for lane in 0..rows { v[(base + 32) * stride + lane] = add(&add(&v[(base + 44) * stride + lane], &v[(base + 49) * stride + lane]), &v[(base + 50) * stride + lane]); }
    for lane in 0..rows { v[(base + 28) * stride + lane] = mul(&v[(base + 16) * stride + lane], &v[(base + 32) * stride + lane]); }
