    for lane in 0..rows { v[(base + 48) * stride + lane] = mul(&v[(base + 16) * stride + lane], &v[(base + 30) * stride + lane]); }
    for lane in 0..rows { v[(base + 55) * stride + lane] = add(&v[(base + 36) * stride + lane], &v[(base + 48) * stride + lane]); }
